    RetrievalFilter.add_member(:not_equals, Types::RetrievalFilter::NotEquals, Smithy::Schema::Shapes::ShapeRef.new(shape: FilterAttribute, location_name: 'notEquals', traits: {"smithy.api#documentation" => "<p>Knowledge base data sources are returned when:</p> <ul> <li> <p>It contains a metadata attribute whose name matches the <code>key</code> and whose value doesn't match the <code>value</code> in this object.</p> </li> <li> <p>The key is not present in the document.</p> </li> </ul> <p>The following example would return data sources that don't contain an <code>animal</code> attribute whose value is <code>cat</code>.</p> <p> <code>\"notEquals\": { \"key\": \"animal\", \"value\": \"cat\" }</code> </p>"}))
